using System.Collections.Generic;

namespace KaiAosRenew
{
    internal static class UiStrings
    {
        private static string _lang = "en";
        private static readonly Dictionary<string, Dictionary<string, string>> Maps =
            new Dictionary<string, Dictionary<string, string>>();

        static UiStrings()
        {
            Maps["en"] = En();
            Maps["ro"] = Ro();
            Maps["de"] = De();
            Maps["da"] = Da();
            Maps["cs"] = Cs();
            Maps["es"] = Es();
            Maps["fr"] = Fr();
            Maps["it"] = It();
            Maps["ja"] = Ja();
            Maps["ko"] = Ko();
            Maps["no"] = No();
            Maps["nl"] = Nl();
            Maps["pl"] = Pl();
            Maps["pt"] = Pt();
            Maps["ru"] = Ru();
            Maps["sv"] = Sv();
            Maps["th"] = Th();
            Maps["tr"] = Tr();
            Maps["zh"] = Zh();
        }

        public static string Language { get { return _lang; } }

        public static void SetLanguage(string code)
        {
            if (string.IsNullOrWhiteSpace(code))
                code = "en";
            _lang = code.Trim().ToLowerInvariant();
            if (_lang == "en-gb" || _lang == "en-us")
                _lang = "en";
        }

        public static string T(string key)
        {
            Dictionary<string, string> map;
            if (Maps.TryGetValue(_lang, out map) && map.ContainsKey(key))
                return map[key];
            if (Maps["en"].ContainsKey(key))
                return Maps["en"][key];
            return key;
        }

        private static Dictionary<string, string> D(params string[] kv)
        {
            var d = new Dictionary<string, string>();
            for (var i = 0; i + 1 < kv.Length; i += 2)
                d[kv[i]] = kv[i + 1];
            return d;
        }

